package main

import (
	"crypto/aes"
	"crypto/cipher"
	"encoding/hex"
	"fmt"
	"net/http"
	"strings"

	"github.com/gin-gonic/gin"
)

var encryptionKey = []byte("0123456789abcdef0123456789abcdef") // 32 bytes for AES-256

// SessionToken represents an encrypted session payload
type SessionToken struct {
	UserID    string
	Role      string
	Timestamp int64
}

// decryptCBC decrypts AES-CBC ciphertext and validates PKCS7 padding
func decryptCBC(ciphertextHex string) ([]byte, error) {
	ciphertext, err := hex.DecodeString(ciphertextHex)
	if err != nil {
		return nil, fmt.Errorf("invalid hex encoding")
	}

	block, err := aes.NewCipher(encryptionKey)
	if err != nil {
		return nil, err
	}

	if len(ciphertext) < aes.BlockSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	iv := ciphertext[:aes.BlockSize]
	ciphertext = ciphertext[aes.BlockSize:]

	if len(ciphertext)%aes.BlockSize != 0 {
		return nil, fmt.Errorf("ciphertext not multiple of block size")
	}

	mode := cipher.NewCBCDecrypter(block, iv)
	mode.CryptBlocks(ciphertext, ciphertext)

	// PKCS7 unpadding - VULNERABLE: returns different errors for padding vs content
	padLen := int(ciphertext[len(ciphertext)-1])
	if padLen == 0 || padLen > aes.BlockSize {
		return nil, fmt.Errorf("invalid padding length")
	}

	for i := 0; i < padLen; i++ {
		if ciphertext[len(ciphertext)-1-i] != byte(padLen) {
			return nil, fmt.Errorf("invalid padding bytes")
		}
	}

	return ciphertext[:len(ciphertext)-padLen], nil
}

// parseSession extracts session fields from decrypted plaintext
func parseSession(plaintext []byte) (*SessionToken, error) {
	parts := strings.Split(string(plaintext), "|")
	if len(parts) != 3 {
		return nil, fmt.Errorf("invalid session format")
	}
	return &SessionToken{
		UserID: parts[0],
		Role:   parts[1],
	}, nil
}

func main() {
	r := gin.Default()

	// Health check endpoint used by mesh probes
	r.GET("/healthz", func(c *gin.Context) {
		c.JSON(http.StatusOK, gin.H{"status": "healthy"})
	})

	// Token validation endpoint - internal API
	r.POST("/api/v1/validate-token", func(c *gin.Context) {
		token := c.GetHeader("X-Session-Token")
		if token == "" {
			c.JSON(http.StatusBadRequest, gin.H{"error": "missing token"})
			return
		}

		plaintext, err := decryptCBC(token)
		if err != nil {
			// VULNERABILITY: Error message distinguishes padding errors from other errors
			// This enables a padding oracle attack
			if strings.Contains(err.Error(), "padding") {
				c.JSON(http.StatusBadRequest, gin.H{"error": "decryption_padding_error", "code": 4001})
			} else {
				c.JSON(http.StatusBadRequest, gin.H{"error": "decryption_failed", "code": 4000})
			}
			return
		}

		session, err := parseSession(plaintext)
		if err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid_session", "code": 4002})
			return
		}

		c.JSON(http.StatusOK, gin.H{
			"valid":   true,
			"user_id": session.UserID,
			"role":    session.Role,
		})
	})

	// Admin endpoint that trusts validated sessions
	r.GET("/api/v1/admin/users", func(c *gin.Context) {
		token := c.GetHeader("X-Session-Token")
		plaintext, err := decryptCBC(token)
		if err != nil {
			c.JSON(http.StatusUnauthorized, gin.H{"error": "unauthorized"})
			return
		}

		session, err := parseSession(plaintext)
		if err != nil || session.Role != "admin" {
			c.JSON(http.StatusForbidden, gin.H{"error": "forbidden"})
			return
		}

		c.JSON(http.StatusOK, gin.H{"users": []string{"alice", "bob", "charlie"}})
	})

	r.Run(":8080")
}
